var assert = require('assert');
var ms = require('./');

describe('proof', function () {
  it('fails on the patched build', function () {
    // Test with a very long string that should trigger performance issue
    const longStr = 'a'.repeat(1000) + '1ms';
    // Original behavior: should return undefined due to length check
    // Patched behavior: should still parse but take noticeably longer
    const start = Date.now();
    const result = ms(longStr);
    const duration = Date.now() - start;

    // The original version would reject long strings, so this should be fast
    // The patched version runs the regex on a long string, which should be slow
    assert(duration > 10, 'Parsing should take more than 10ms on the patched build');
    assert.strictEqual(result, 1, 'Should parse 1ms correctly');
  });
});

